// normalize the LLM's free-text reply down to a clean category string
const raw = ($json.message?.content || $json.text || '').toLowerCase().trim();
const allowed = ['automation-heavy', 'web dev', 'data', 'ai/ml'];
const matched = allowed.find(c => raw.includes(c)) || 'other';
return { person_id: $('Split into one item per person').item.json.person_id, skill_category: matched };
